/* Reset and base styles */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
  line-height: 1.6;
  color: #333;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  min-height: 100vh;
  padding: 20px;
}

/* Layout */
.site-header {
  text-align: center;
  color: #fff;
  margin-bottom: 40px;
  padding: 20px 0;
}

.site-header h1 {
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: 2px;
  margin-bottom: 10px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

.subtitle {
  color: #e0e0e0;
  font-size: 1.1rem;
  font-weight: 300;
}

.event-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

/* Event Cards */
.event-card {
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  display: flex;
  flex-direction: column;
}

.event-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.3);
}

.event-card__image {
  height: 200px;
  position: relative;
  background-size: cover;
  background-position: center;
}

.event-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Dawn Jazz Image */
.dawn-image {
  background: linear-gradient(135deg, #ff9a9e 0%, #fecfef 50%, #a18cd1 100%);
}

/* River Lantern Image */
.river-image {
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 50%, #43e97b 100%);
}

/* Midnight Image */
.midnight-image {
  background: linear-gradient(135deg, #240b36 0%, #c31432 50%, #614385 100%);
}

.event-card__content {
  padding: 24px;
  flex: 1;
}

.event-card__title {
  font-size: 1.5rem;
  color: #1a1a2e;
  margin-bottom: 12px;
}

.event-card__description {
  color: #666;
  margin-bottom: 20px;
  line-height: 1.7;
}

.event-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
  padding-top: 16px;
  border-top: 1px solid #eee;
}

.event-card__time,
.event-card__location {
  font-size: 0.9rem;
  color: #888;
  display: flex;
  align-items: center;
  gap: 6px;
}

.event-card__time::before {
  content: '🕒';
}

.event-card__location::before {
  content: '📍';
}

.event-card__sold-out {
  background: #e74c3c;
  color: #fff;
  padding: 8px 16px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  text-align: center;
  margin-top: 12px;
}

/* Footer and Button */
.site-footer {
  text-align: center;
  margin-top: 40px;
  padding: 30px 20px;
}

.show-sold-out-btn {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: #fff;
  border: none;
  padding: 16px 40px;
  font-size: 1.1rem;
  font-weight: 600;
  border-radius: 50px;
  cursor: pointer;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  box-shadow: 0 5px 15px rgba(102, 126, 234, 0.4);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.show-sold-out-btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(102, 126, 234, 0.6);
}

.show-sold-out-btn:focus {
  outline: 3px solid #667eea;
  outline-offset: 3px;
}

/* Hidden state for sold-out card */
.sold-out-card.hidden {
  display: none;
}

/* Responsive Design */
@media (max-width: 768px) {
  .site-header h1 {
    font-size: 1.8rem;
  }

  .subtitle {
    font-size: 1rem;
  }

  .event-container {
    grid-template-columns: 1fr;
    max-width: 400px;
  }

  .event-card__image {
    height: 180px;
  }
}

/* Mobile 375px optimization */
@media (max-width: 375px) {
  body {
    padding: 15px;
  }

  .site-header h1 {
    font-size: 1.5rem;
  }

  .event-card__content {
    padding: 16px;
  }

  .event-card__title {
    font-size: 1.25rem;
  }

  .event-card__description {
    font-size: 0.95rem;
  }

  .show-sold-out-btn {
    padding: 12px 30px;
    font-size: 1rem;
  }
}

/* Reduced motion preference */
@media (prefers-reduced-motion: reduce) {
  .event-card,
  .show-sold-out-btn {
    transition: none;
  }
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  .event-card {
    border: 2px solid #333;
  }

  .event-card__title {
    font-weight: 700;
  }
}

/**
 * Night Garden FLEET-46a18f0dea
 * Event website JavaScript
 */

(function() {
  'use strict';

  // DOM elements
  const showSoldOutBtn = document.getElementById('show-sold-out-btn');
  const midnightCard = document.getElementById('midnight-card');

  /**
   * Show the sold-out concert card
   */
  function showSoldOutCard() {
    if (midnightCard) {
      midnightCard.classList.remove('hidden');
    }
  }

  /**
   * Event handler for the "Show sold out" button
   * @param {Event} event - The click event
   */
  function handleShowSoldOutClick(event) {
    event.preventDefault();
    showSoldOutCard();

    // Update button text to indicate the action
    if (showSoldOutBtn) {
      showSoldOutBtn.textContent = 'Sold out revealed';
    }
  }

  /**
   * Initialize event listeners
   */
  function init() {
    // Add click event listener to the button
    if (showSoldOutBtn) {
      showSoldOutBtn.addEventListener('click', handleShowSoldOutClick);
    }
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

